const crypto = require('crypto');
const sha256 = (value) => crypto.createHash('sha256').update(value).digest('hex');
const goal = 'Verify canonical V3 receipt hashing inside pinned n8n runtime.';
const projectSlug = 'founder-control-room';
const expectedHeadSha = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';
const registryHash = 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb';
const strategicLenses = ['truthmode'];
const routingReason = 'Verify pinned n8n can recompute a Chief-AI-authored V10 capability plan and its bound receipt.';
const capabilities = [
  ['capability-mode-router','1.0.0','repo-native','chief-ai-machine','cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc','privileged'],
  ['lean-build-orchestrator','1.0.0','repo-native','chief-ai-machine','dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd','privileged'],
  ['regression-stagnation-guard','1.0.0','repo-native','chief-ai-machine','eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee','privileged'],
];
const proofRequirements = ['canonical receipt hash','pinned n8n import'];
const outcomeSignals = ['n8n-runtime-compatible'];
const rollback = 'Discard compatibility fixture.';
const planSeed = JSON.stringify(['juss-v10/capability-plan@v1','chief-ai-machine',goal,projectSlug,expectedHeadSha,registryHash,'draft',strategicLenses,routingReason,capabilities,proofRequirements,outcomeSignals,rollback]);
const capabilityPlanHash = sha256(planSeed);
const expectedPlanHash = 'ac26cec405a9f353cb76b6739744f2baa0e10142463a608126c7c55ef6bb260d';
if (capabilityPlanHash !== expectedPlanHash) throw new Error(`capability plan mismatch: ${capabilityPlanHash}`);
const idempotencyKey = `fcr-conveyor-v3:${sha256(['compat-run',projectSlug,'workflows','code',expectedHeadSha,capabilityPlanHash].join(':'))}`;
const expectedIdempotency = 'fcr-conveyor-v3:e78125f31ca297d6a2f1a2b0800901a971e0848b13546089e9908aeed8e0500a';
if (idempotencyKey !== expectedIdempotency) throw new Error(`idempotency mismatch: ${idempotencyKey}`);
const skillIds = capabilities.map((capability) => capability[0]).sort();
const evidenceUrls = ['https://github.com/jussray/founder-control-room/commit/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'];
const receiptSeed = JSON.stringify([idempotencyKey,'compat-run',projectSlug,goal,expectedHeadSha,'workflows','code',capabilityPlanHash,registryHash,skillIds,evidenceUrls]);
const receiptId = `fcr-conveyor-receipt-v3:${sha256(receiptSeed)}`;
const expected = 'fcr-conveyor-receipt-v3:4cbb74cbfdcc3937a91b3d25c1c25722c766d239bae42a2132851f0228eb90bf';
if (receiptId !== expected) throw new Error(`receipt mismatch: ${receiptId}`);
return [{ json: { verified: true, receiptId, capabilityPlanHash, registryHash, runtimeContract: 'n8n@2.32.6+crypto' } }];
